insert into courses (id, slug, title, topic, level, language, summary, description, suits, outcomes, prereq, materials, cover_url, preview_video, preview_captions, preview_poster, group_id, access, price, order_rule, asg_rule, status, is_sample, created_at, published_at) values (md5('course:cashflow')::uuid, $q$build-your-first-cash-flow-forecast$q$, $q$Build Your First Cash Flow Forecast$q$, $q$Cash flow & finance$q$, $q$Beginner$q$, $q$English$q$, $q$See next month’s cash before it arrives. Build a simple one-month forecast you can update in 10 minutes a week.$q$, array[$q$Most small businesses that run short of cash are profitable on paper. The problem is timing: customers pay late while rent, payroll and HST are due on fixed dates.$q$,$q$In this course, Ottawa bookkeeper Sara Haddad walks you through cash coming in and cash going out, then you build a real one-month forecast for your own business using our worksheet. Sara reviews your forecast and sends feedback.$q$]::text[], array[$q$Owners with no accounting background$q$,$q$Anyone who has been surprised by a low bank balance$q$,$q$First-year owners preparing to talk to a bank$q$]::text[], array[$q$Sort every payment into cash coming in and cash going out$q$,$q$Build a one-month, week-by-week cash flow forecast$q$,$q$Spot a short week early and pick one action to fix it$q$]::text[], array[$q$None. Basic spreadsheet skills help.$q$]::text[], array[$q$Last month’s bank statement$q$,$q$A list of unpaid customer invoices$q$,$q$Excel, Google Sheets or Numbers$q$]::text[], $q$/sample/courses/course-cashflow.jpg$q$, $q$sample/cf-preview.mp4$q$, $q$sample/cf-preview.vtt$q$, $q$/sample/courses/cf-preview.jpg$q$, (select id from groups where slug = 'money-tax-and-bookkeeping'), $q$free$q$, 0, $q$seq$q$, $q$submit$q$, $q$draft$q$, true, now() - interval '172800 seconds', null);
