insert into lessons (id, course_id, section_id, title, type, minutes, free_preview, drip_days, position) values (md5('course:cashflow:l3')::uuid, md5('course:cashflow')::uuid, md5('course:cashflow:s2')::uuid, $q$Set up your forecast worksheet$q$, $q$text$q$, 8, false, 0, 0);
insert into lesson_content (lesson_id, course_id, body, video_path, captions_path, poster_url) values (md5('course:cashflow:l3')::uuid, md5('course:cashflow')::uuid, array[$q$Download the worksheet below. It has one column for each week of the month and fills in totals for you.$q$,$q$1. Enter your opening cash: the balance in your business bank account on the first day of the month.$q$,$q$2. Under Cash coming in, enter the customer payments you expect each week. Use the date the money will arrive, not the invoice date.$q$,$q$3. Under Cash going out, enter rent, payroll, supplier bills, HST remittances, loan payments and what you pay yourself.$q$,$q$4. Check the Closing cash row. If any week ends below zero, write one action you will take, such as calling a customer about a late invoice or moving a supplier payment.$q$]::text[], '', '', '');
