insert into submissions (member_id, lesson_id, course_id, body, file_path, file_name, file_size, submitted_at, grade_marks, feedback, graded_by, graded_at, seen_at) values ((select id from auth.users where email = 'marcus@demo.invalid'), md5('course:marketing200:l7')::uuid, md5('course:marketing200')::uuid, $q$Plan attached. Most of it goes to a boosted post and a sidewalk sign.$q$, '', $q$Marcus-200-dollar-plan.pdf$q$, 182000, now() - interval '604800 seconds', null, '', null, null, null);
insert into submissions (member_id, lesson_id, course_id, body, file_path, file_name, file_size, submitted_at, grade_marks, feedback, graded_by, graded_at, seen_at) values ((select id from auth.users where email = 'luc@demo.invalid'), md5('course:marketing200:l7')::uuid, md5('course:marketing200')::uuid, $q$Google profile first ($0). $120 on two weeks of boosted posts for our new menu. $80 on table cards with a QR code for reviews. Tracking: a question on the order form, How did you hear about us?$q$, '', $q$$q$, 0, now() - interval '18000 seconds', null, '', null, null, null);
